function APR.currentStep:ShowHeaderMenu(owner)
    -- Addon-created native context menus can contaminate Forever's gamepad
    -- focus state. Use APR's registered popup for every header entry point.
    if APR.Gamepad and APR.Gamepad:IsEnabled() then
        APR.Gamepad:RunAction("menu")
    else
        MenuUtil.CreateContextMenu(owner, APR.GetMenu)
    end
