-- Refresh the frame positioning
function APR.currentStep:RefreshCurrentStepFrameAnchor()
    if InCombatLockdown() then
        self.pendingAnchorRefresh = true
        return
    end
    self.pendingAnchorRefresh = nil
    if APR.RouteSelection then APR.RouteSelection:RefreshFrameAnchor() end
    APR:Debug("Function: APR:RefreshCurrentStepFrameAnchor()")
    -- Use centralized frame hiding check from Core
    if APR:ShouldHideFrames() then
        if APR.QuestTracker then APR.QuestTracker:Release() end
        CurrentStepScreenPanel:Hide()

        -- When CurrentStep hides, refresh all child frames
        if APR.AFK and APR.AFK.RefreshFrameAnchor then
            APR.AFK:RefreshFrameAnchor()
        end
        if APR.fillersFrame and APR.fillersFrame.RefreshFillersFrame then
            APR.fillersFrame:RefreshFillersFrame()
        end
        if APR.questOrderList and APR.questOrderList.ApplySnapAnchor then
            APR.questOrderList:ApplySnapAnchor()
        end
        return
    end

    local profile = APR:GetSettingsProfile()
    if not profile then return end

    self:RefreshResizeHandle()

    if profile.currentStepAttachFrameToQuestLog then
        if not InCombatLockdown() then
            CurrentStepScreenPanel:EnableMouse(false)
        end
        self:RefreshQuestTrackerAnchor()
    else
        trackerAnchorX, trackerAnchorY = nil, nil
        if APR.SetFrameSnapAnchor then APR:SetFrameSnapAnchor(CurrentStepScreenPanel, nil) end
        if APR.QuestTracker then APR.QuestTracker:Release() end
        if not InCombatLockdown() then
            if not profile.currentStepLock then
                CurrentStepScreenPanel:EnableMouse(true)
            else
                CurrentStepScreenPanel:EnableMouse(false)
            end

            LibWindow.RestorePosition(CurrentStepScreenPanel)
            self:UpdateFrameScale()
        end
    end
    CurrentStepFrameHeader:ClearAllPoints()
    CurrentStepFrameHeader:SetPoint("BOTTOM", CurrentStepFrame, "TOP", 0, -1)

    -- InCombatLockdown to prevent the "UNKNOWN()"-Call issue which happens sometimes when we're in a combat and doing a quest step
    if not InCombatLockdown() then
        CurrentStepScreenPanel:Show()
        APR:RefreshSnappedFrames()
        if profile.currentStepAttachFrameToQuestLog then self:RefreshQuestTrackerAnchor() end
    end
end--[[APR_DIAG]]; APR.currentStep.RefreshCurrentStepFrameAnchor = APRTrace("APR-Core/ui/route/CurrentStep.lua:563:APR.currentStep:RefreshCurrentStepFrameAnchor#37", APR.currentStep.RefreshCurrentStepFrameAnchor)--[[/APR_DIAG]]

local function ConsiderBottom(frame, minBottom)
    if frame and frame:IsShown() then
        local bottom = frame:GetBottom()
        if bottom and bottom < minBottom then return bottom end
    end
    return minBottom
end--[[APR_DIAG]]; ConsiderBottom = APRTrace("APR-Core/ui/route/CurrentStep.lua:625:ConsiderBottom#38", ConsiderBottom)--[[/APR_DIAG]]

local function ConsiderListBottom(list, minBottom)
    for _, container in pairs(list) do
        if container and container:IsShown() then
            minBottom = ConsiderBottom(container, minBottom)
            minBottom = ConsiderBottom(container.IconButton, minBottom)
            minBottom = ConsiderBottom(container.RaidIconButton, minBottom)
        end
    end
    return minBottom
end--[[APR_DIAG]]; ConsiderListBottom = APRTrace("APR-Core/ui/route/CurrentStep.lua:633:ConsiderListBottom#39", ConsiderListBottom)--[[/APR_DIAG]]

function APR.currentStep:GetContentHeight(includeFillers)
    if not CurrentStepScreenPanel then
        return nil
    end
    if CurrentStepScreenPanel.collapsed then return CurrentStepScreenPanel:GetHeight() end

    if includeFillers == nil then
        includeFillers = true
    end

    local top = CurrentStepScreenPanel:GetTop()
    local minBottom = CurrentStepScreenPanel:GetBottom()

    if not top or not minBottom then
        return nil
    end

    minBottom = ConsiderBottom(CurrentStepFrameHeader, minBottom)
    minBottom = ConsiderBottom(CurrentStepFrame_StepHolder and CurrentStepFrame_StepHolder.rollbackButton, minBottom)
    minBottom = ConsiderBottom(CurrentStepFrame_StepHolder and CurrentStepFrame_StepHolder.skipButton, minBottom)
    minBottom = ConsiderBottom(self.progressBar, minBottom)
    minBottom = ConsiderBottom(self.contentBackdrop, minBottom)
    minBottom = ConsiderBottom(self.emptyRoutePrompt, minBottom)
    minBottom = ConsiderListBottom(self.questsExtraTextList, minBottom)
    minBottom = ConsiderListBottom(self.questsList, minBottom)

    -- Consider the fillers frame
    if includeFillers and APR.fillersFrame and APR.fillersFrame.Frame and APR.fillersFrame.Frame:IsShown() then
        minBottom = ConsiderBottom(APR.fillersFrame.Frame, minBottom)
        minBottom = ConsiderListBottom(self.fillersList, minBottom)
    end

    return top - minBottom
end--[[APR_DIAG]]; APR.currentStep.GetContentHeight = APRTrace("APR-Core/ui/route/CurrentStep.lua:644:APR.currentStep:GetContentHeight#40", APR.currentStep.GetContentHeight)--[[/APR_DIAG]]

