-- Add a progress bar
function APR.currentStep:ProgressBar(key, total, current)
    local profile = APR:GetSettingsProfile()
    if not profile or not profile.currentStepShow then
        return
    end

    local totalSteps = total or 0
    local currentStep = current or 0
    local service = APR.Services and APR.Services:GetStep()
    local stepName
    if service then
        currentStep, totalSteps, stepName = APR.Services:GetProgress()
        key = service
    end

    if not self.progressBar then
        local progressBar = APR:CreateStatusBar(CurrentStepFrameHeader, "CurrentStepFrame_StepHolder_ProgressBar")
        progressBar:SetSize(self:GetProgressBarWidth(), 18)
        progressBar:SetPoint("BOTTOM", CurrentStepFrameHeader, "BOTTOM", 0, -25)
        progressBar:SetMinMaxValues(0, math.max(totalSteps, 1))
        progressBar:SetValue(currentStep)
        progressBar:SetBackdrop({
            bgFile = "Interface\\Tooltips\\UI-Tooltip-Background",
            tile = true,
            tileSize = 16,
        })
        APR:SetPanelColor(progressBar, APR.Color.defaultBackdrop)

        local progressBarText = progressBar.Text
        if totalSteps > 0 then
            progressBarText:SetText(currentStep .. " / " .. totalSteps)
        else
            progressBarText:SetText("")
        end
        self.progressBar = progressBar
        self.progressBar.Text = progressBarText
        self.progressBar.key = key
        self.progressBar.currentStep = currentStep
    else
        local width = self:GetProgressBarWidth()
        if self.progressBar:GetWidth() ~= width then self.progressBar:SetWidth(width) end
        self.progressBar:SetMinMaxValues(0, math.max(totalSteps, 1))
        self.progressBar.key = key
        self.progressBar:SetValue(currentStep)
        self.progressBar.currentStep = currentStep
        if totalSteps > 0 then
            self.progressBar.Text:SetText(currentStep .. " / " .. totalSteps)
        else
            self.progressBar.Text:SetText("")
        end
        self:UpdateProgressBarColor(self.progressBar)
    end

    -- A refresh can rebuild the progress bar while the frame is collapsed.
    -- Keep header-owned controls hidden until the user expands the frame.
    local text = self.progressBar.Text
    text:SetWidth(self:GetProgressBarWidth() - 8)
    text:SetWordWrap(false)
    if service then
        text:SetText((totalSteps > 0 and (currentStep .. " / " .. totalSteps .. " - ") or "") .. (stepName or ""))
    end
    if CurrentStepFrame.collapsed or self.emptyRoutePromptActive then
        self.progressBar:Hide()
    else
        self.progressBar:Show()
    end
end--[[APR_DIAG]]; APR.currentStep.ProgressBar = APRTrace("APR-Core/ui/route/CurrentStep.lua:815:APR.currentStep:ProgressBar#54", APR.currentStep.ProgressBar)--[[/APR_DIAG]]

