function APR.currentStep:AddObjectiveProgressBar(container, key, current, total, text, replaceText)
    local owner = (replaceText or key == "questProgressBar") and container or self
    local bar = owner[key]
    if not current then
        if bar then bar:Hide() end
        container.extraContentHeight = nil
        self:ReOrderQuestSteps()
        return
    end
    if not bar then
        bar = APR:CreateStatusBar(container)
        owner[key] = bar
    end
    -- Reuse the bar across resource refreshes; its row owns visibility and cleanup.
    bar:SetParent(container)
    bar:ClearAllPoints()
    if replaceText then
        bar:SetPoint("TOPLEFT", container, "TOPLEFT", 16, -5)
        bar:SetPoint("TOPRIGHT", container, "TOPRIGHT", -16, -5)
        container.font:Hide()
        container.progressBarOnly = true
    else
        bar:SetPoint("TOPLEFT", container.font, "BOTTOMLEFT", 0, -5)
        bar:SetPoint("TOPRIGHT", container.font, "BOTTOMRIGHT", 0, -5)
    end
    bar:SetHeight(20)
    self:UpdateProgressBarColor(bar)
    bar:SetMinMaxValues(0, total)
    bar:SetValue(current)
    bar.Text:SetText(text)
    bar:Show()
    container.extraContentHeight = replaceText and 0 or 25
    self:ReOrderQuestSteps()
end--[[APR_DIAG]]; APR.currentStep.AddObjectiveProgressBar = APRTrace("APR-Core/ui/route/CurrentStep.lua:939:APR.currentStep:AddObjectiveProgressBar#60", APR.currentStep.AddObjectiveProgressBar)--[[/APR_DIAG]]

function APR.currentStep:UpdateQuestObjectiveProgressBar(container, questID, objectiveIndex)
    local percent = container.isQuestObjective and APR:GetQuestObjectiveProgressPercent(questID, objectiveIndex)
    if percent then
        local bar = container.questProgressBar
        -- IsShown is intentional: a collapsed parent must not invalidate the
        -- cached value. Recycled/explicitly hidden bars are initialized again.
        if bar and bar:IsShown() and container.extraContentHeight == 25 and not container.progressBarOnly then
            if container.questProgressPercent ~= percent then
                bar:SetValue(percent)
                bar.Text:SetText(percent .. "%")
                container.questProgressPercent = percent
            end
            return
        end
        container.questProgressPercent = percent
        self:AddObjectiveProgressBar(container, "questProgressBar", percent, 100, percent .. "%")
    elseif
        container.questProgressBar
        and (container.questProgressBar:IsShown() or container.extraContentHeight ~= nil or container.progressBarOnly)
    then
        container.questProgressPercent = nil
        container.questProgressBar:Hide()
        container.progressBarOnly = nil
        container.extraContentHeight = nil
        container.font:Show()
        self:ReOrderQuestSteps()
    end
end--[[APR_DIAG]]; APR.currentStep.UpdateQuestObjectiveProgressBar = APRTrace("APR-Core/ui/route/CurrentStep.lua:974:APR.currentStep:UpdateQuestObjectiveProgressBar#61", APR.currentStep.UpdateQuestObjectiveProgressBar)--[[/APR_DIAG]]

