function APR.currentStep:CanSafelyHide(container)
    -- Retired secure children still belong to their row. Remember this even
    -- after the active button reference is cleared so reused rows stay safe.
    return not InCombatLockdown()
        or not (
            -- Sibling raid buttons also protect their anchor row, even though
            -- they are absent from the row's own secure-control references.
            container:IsProtected()
            or container.hasSecureControls
            or (container.IconButton and container.IconButton:IsProtected())
            or (container.RaidIconButton and container.RaidIconButton:IsProtected())
        )
end--[[APR_DIAG]]; APR.currentStep.CanSafelyHide = APRTrace("APR-Core/ui/route/CurrentStep.lua:1851:APR.currentStep:CanSafelyHide#121", APR.currentStep.CanSafelyHide)--[[/APR_DIAG]]

function APR.currentStep:SoftHide(container)
    container.hiddenInCombat = true
    container:SetAlpha(0.001)
    -- Strip tooltip scripts to prevent ghost tooltips (safe in combat)
    container:SetScript("OnEnter", nil)
    container:SetScript("OnLeave", nil)
    -- EnableMouse is protected on secure frames; only call outside combat
    if not InCombatLockdown() then
        container:EnableMouse(false)
    end
    if container.IconButton then
        container.IconButton:SetScript("OnEnter", nil)
        container.IconButton:SetScript("OnLeave", nil)
        if not InCombatLockdown() then
            container.IconButton:EnableMouse(false)
        end
    end
    if container.RaidIconButton then
        container.RaidIconButton:SetScript("OnEnter", nil)
        container.RaidIconButton:SetScript("OnLeave", nil)
        if not InCombatLockdown() then
            container.RaidIconButton:EnableMouse(false)
        end
    end
end--[[APR_DIAG]]; APR.currentStep.SoftHide = APRTrace("APR-Core/ui/route/CurrentStep.lua:1865:APR.currentStep:SoftHide#122", APR.currentStep.SoftHide)--[[/APR_DIAG]]

function APR.currentStep:FlushPendingContainers()
    if InCombatLockdown() then return end
    if self.pendingAnchorRefresh then self:RefreshCurrentStepFrameAnchor() end
    -- Flush orphaned containers (replaced during combat)
    for _, container in ipairs(self.pendingContainerDestroy) do
        self:RecycleRow(container)
    end
    wipe(self.pendingContainerDestroy)

    if not next(self.pendingRemoval) then
        if self.layoutDirty then self:ReOrderQuestSteps() end
        if APR.fillersFrame and APR.fillersFrame.FlushPendingLayout then APR.fillersFrame:FlushPendingLayout() end
        APR:RefreshSnappedFrames()
        return
    end
    for id, _ in pairs(self.pendingRemoval) do
        for _, list in ipairs({ self.questsList, self.questsExtraTextList, self.fillersList }) do
            self:ReleaseRow(list, id)
        end
    end
    wipe(self.pendingRemoval)
    self:ReOrderQuestSteps(true)
    if APR.fillersFrame then
        APR.fillersFrame:ReOrderFillerSteps()
    end
end--[[APR_DIAG]]; APR.currentStep.FlushPendingContainers = APRTrace("APR-Core/ui/route/CurrentStep.lua:1891:APR.currentStep:FlushPendingContainers#123", APR.currentStep.FlushPendingContainers)--[[/APR_DIAG]]

-- The party wire may omit an oversized tooltip, but must retain its progress.
-- Bound construction before copying/sorting rows that would then be discarded.
local function ReserveSnapshotRow(budget, text)
    budget.rows = budget.rows - 1
    if budget.rows < 0 then return false end
    if text ~= nil then
        if type(text) ~= "string" then return false end
        budget.bytes = budget.bytes - #text
        if budget.bytes < 0 then return false end
    end
    return true
end--[[APR_DIAG]]; ReserveSnapshotRow = APRTrace("APR-Core/ui/route/CurrentStep.lua:1920:ReserveSnapshotRow#124", ReserveSnapshotRow)--[[/APR_DIAG]]

local function OmitSnapshotRows(details)
    details.extraLines, details.questSteps = {}, {}
    if details.fillerSteps then details.fillerSteps = {} end
    return details
end--[[APR_DIAG]]; OmitSnapshotRows = APRTrace("APR-Core/ui/route/CurrentStep.lua:1931:OmitSnapshotRows#125", OmitSnapshotRows)--[[/APR_DIAG]]

function APR.currentStep:GetCurrentStepDetails(includeFillers, maxRows, maxBytes)
    if not APR.ActiveRoute then return nil end
    local playerData = APRData and APRData[APR.PlayerID] or {}
    local currentIndex = playerData[APR.ActiveRoute]
    local progressBar = self.progressBar
    local displayedStep
    if progressBar and progressBar.key == APR.ActiveRoute and type(progressBar.currentStep) == "number" then
        displayedStep = progressBar.currentStep
    elseif type(currentIndex) == "number" then
        displayedStep = currentIndex - APR:CountSkippedStepsBefore(APR.ActiveRoute, currentIndex)
    end

    local stepDetails = {
        extraLines = {},
        questSteps = {},
        fillerSteps = includeFillers ~= false and {} or nil,
        progress = {
            index = currentIndex,
            step = displayedStep,
            total = playerData[APR.ActiveRoute .. "-TotalSteps"],
        },
    }

    local budget
    if
        type(maxRows) == "number"
        and maxRows >= 0
        and maxRows < math.huge
        and maxRows % 1 == 0
        and type(maxBytes) == "number"
        and maxBytes >= 0
        and maxBytes < math.huge
        and maxBytes % 1 == 0
    then
        budget = { rows = maxRows, bytes = maxBytes }
    end

    -- Extra lines
    for key, container in pairs(self.questsExtraTextList) do
        local text = container.font and container.font:GetText()
        if text then
            if budget and not ReserveSnapshotRow(budget, text) then return OmitSnapshotRows(stepDetails) end
            table.insert(stepDetails.extraLines, {
                key = key,
                text = text,
            })
        end
    end

    -- Quest steps
    for key, container in pairs(self.questsList) do
        local text = container.font and container.font:GetText()
        if text then
            if budget and not ReserveSnapshotRow(budget, text) then return OmitSnapshotRows(stepDetails) end
            local step = {
                key = key,
                text = text,
            }

            -- Add sub-steps if they exist
            if container.subTexts then
                step.subSteps = {}
                for _, sub in ipairs(container.subTexts) do
                    local subText = sub.text
                    if budget and (type(subText) ~= "string" or not ReserveSnapshotRow(budget, subText)) then
                        return OmitSnapshotRows(stepDetails)
                    end
                    table.insert(step.subSteps, {
                        questID = sub.questID,
                        name = sub.name,
                        text = subText,
                    })
                end
            end

            table.insert(stepDetails.questSteps, step)
        end
    end

    -- Fillers are not consumed by the party tooltip.
    if includeFillers ~= false then
        for key, container in pairs(self.fillersList) do
            local text = container.font and container.font:GetText()
            if text then
                if budget and not ReserveSnapshotRow(budget, text) then return OmitSnapshotRows(stepDetails) end
                table.insert(stepDetails.fillerSteps, {
                    key = key,
                    text = text,
                })
            end
        end
    end

    -- Stable order prevents a recycled row from changing an otherwise identical
    -- snapshot just because Lua's table traversal order changed.
    local function ByKey(a, b) return tostring(a.key) < tostring(b.key) end--[[APR_DIAG]]; ByKey = APRTrace("APR-Core/ui/route/CurrentStep.lua:2032:ByKey#127", ByKey)--[[/APR_DIAG]]
    table.sort(stepDetails.extraLines, ByKey)
    table.sort(stepDetails.questSteps, ByKey)
    return stepDetails
end--[[APR_DIAG]]; APR.currentStep.GetCurrentStepDetails = APRTrace("APR-Core/ui/route/CurrentStep.lua:1937:APR.currentStep:GetCurrentStepDetails#126", APR.currentStep.GetCurrentStepDetails)--[[/APR_DIAG]]
